// Value: protects=clopperPearson returns the exact two-sided 95% bounds and rejects counts outside 0 <= x <= n; fails_when=the bisection direction, the alpha/2 split or the x=0/x=n edges change; why_new=no test imported src/runner/stats/exact.ts; seam=none; no_claim=none beyond protects
// Generated by gstack /ship (U2 ship gate). Reference values: closed forms for x = 0 and x = n, and published Clopper-Pearson tables for 5/10.
import { describe, expect, test } from "bun:test";
import { binomialCdf, clopperPearson } from "../../src/runner/stats/exact.ts";

describe("binomialCdf", () => {
  test("matches hand-computed tails and clamps at the edges", () => {
    expect(binomialCdf(2, 5, 0.5)).toBeCloseTo(0.5, 12);
    expect(binomialCdf(0, 4, 0.5)).toBeCloseTo(1 / 16, 12);
    expect(binomialCdf(-1, 5, 0.3)).toBe(0);
    expect(binomialCdf(5, 5, 0.3)).toBe(1);
    expect(binomialCdf(2, 5, 0)).toBe(1);
    expect(binomialCdf(2, 5, 1)).toBe(0);
  });
});

describe("clopperPearson", () => {
  test("x = 0 and x = n use the closed forms", () => {
    const none = clopperPearson(0, 10);
    expect(none.lower).toBe(0);
    expect(none.upper).toBeCloseTo(1 - 0.025 ** (1 / 10), 6);
    const all = clopperPearson(10, 10);
    expect(all.lower).toBeCloseTo(0.025 ** (1 / 10), 6);
    expect(all.upper).toBe(1);
  });

  test("5 of 10 matches the published interval and is symmetric", () => {
    const { lower, upper } = clopperPearson(5, 10);
    expect(lower).toBeCloseTo(0.187086, 5);
    expect(upper).toBeCloseTo(0.812914, 5);
    expect(lower + upper).toBeCloseTo(1, 9);
  });

  test("a wider alpha gives a narrower interval", () => {
    const at95 = clopperPearson(3, 20);
    const at80 = clopperPearson(3, 20, 0.2);
    expect(at80.lower).toBeGreaterThan(at95.lower);
    expect(at80.upper).toBeLessThan(at95.upper);
  });

  test("rejects counts that are not integers with 0 <= x <= n and n > 0", () => {
    for (const [x, n] of [[-1, 10], [11, 10], [1, 0], [1.5, 10], [1, 10.5]]) {
      expect(() => clopperPearson(x, n)).toThrow("clopperPearson needs integers");
    }
  });
});
